* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: linear-gradient(135deg, #1e2a3a 0%, #2d3e50 100%);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  color: #e8edf2;
}

.game-container {
  background: #2a3b4c;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.5);
  max-width: 600px;
  width: 100%;
}

.game-header {
  text-align: center;
  margin-bottom: 20px;
}

h1 {
  font-size: 1.8rem;
  font-weight: 600;
  color: #f0c75e;
  margin-bottom: 12px;
  letter-spacing: 0.5px;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #1e2a3a;
  padding: 10px 18px;
  border-radius: 40px;
  font-size: 1.1rem;
  font-weight: 500;
}

#moveCounter {
  color: #f0c75e;
  font-weight: 700;
}

button {
  background: #f0c75e;
  color: #1e2a3a;
  border: none;
  border-radius: 40px;
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  font-family: inherit;
}

button:hover {
  background: #f5d98a;
}

button:focus-visible {
  outline: 3px solid #f0c75e;
  outline-offset: 3px;
}

button:active {
  transform: scale(0.96);
}

.win-message {
  background: #f0c75e;
  color: #1e2a3a;
  padding: 12px;
  border-radius: 12px;
  text-align: center;
  font-weight: 700;
  font-size: 1.2rem;
  margin-bottom: 16px;
  animation: pop 0.4s ease;
}

@keyframes pop {
  0% { transform: scale(0.8); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  aspect-ratio: 1 / 1;
  max-width: 500px;
  margin: 0 auto;
}

.card {
  background: #3e5266;
  border-radius: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  transition: background 0.25s, transform 0.2s;
  user-select: none;
  position: relative;
  aspect-ratio: 1 / 1;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
}

.card:hover:not(.matched):not(.flipped) {
  background: #4e6a82;
  transform: scale(1.03);
}

.card:focus-visible {
  outline: 3px solid #f0c75e;
  outline-offset: 2px;
}

.card.flipped, .card.matched {
  background: #f0c75e;
  color: #1e2a3a;
  cursor: default;
}

.card.matched {
  opacity: 0.7;
  transform: scale(0.97);
}

.card .card-content {
  display: none;
  font-size: 2rem;
}

.card.flipped .card-content,
.card.matched .card-content {
  display: block;
}

.card::before {
  content: "?";
  font-size: 1.8rem;
  font-weight: 700;
  color: #8fa8c0;
  position: absolute;
}

.card.flipped::before,
.card.matched::before {
  display: none;
}

@media (max-width: 480px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .game-board {
    gap: 8px;
  }
  .card {
    font-size: 1.5rem;
  }
  .card::before {
    font-size: 1.4rem;
  }
  .card .card-content {
    font-size: 1.5rem;
  }
  .status-bar {
    font-size: 0.95rem;
    padding: 8px 14px;
  }
  button {
    padding: 8px 16px;
    font-size: 0.95rem;
  }
}

const gameBoard = document.getElementById('gameBoard');
const moveCounter = document.getElementById('moveCounter');
const winMessage = document.getElementById('winMessage');
const newGameBtn = document.getElementById('newGameBtn');

const COLORS = [
  '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
  '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
];

let deck = [];
let flipped = [];
let matchedPairs = 0;
let moves = 0;
let lockBoard = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createDeck() {
  const cards = [];
  COLORS.forEach((color, index) => {
    cards.push({ color, pairId: index });
    cards.push({ color, pairId: index });
  });
  return shuffle(cards);
}

function renderBoard() {
  gameBoard.innerHTML = '';
  deck.forEach((cardData, index) => {
    const card = document.createElement('div');
    card.className = 'card';
    card.setAttribute('role', 'button');
    card.setAttribute('tabindex', '0');
    card.setAttribute('aria-label', 'Hidden card');
    card.dataset.index = index;
    card.dataset.pairId = cardData.pairId;

    const content = document.createElement('span');
    content.className = 'card-content';
    content.textContent = '●';
    content.style.color = cardData.color;
    card.appendChild(content);

    card.addEventListener('click', handleCardClick);
    card.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        handleCardClick(e);
      }
    });

    gameBoard.appendChild(card);
  });
}

function handleCardClick(e) {
  const card = e.currentTarget;
  if (lockBoard) return;
  if (card.classList.contains('flipped') || card.classList.contains('matched')) return;

  card.classList.add('flipped');
  card.setAttribute('aria-label', 'Flipped card');
  flipped.push(card);

  if (flipped.length === 2) {
    moves++;
    moveCounter.textContent = moves;
    checkMatch();
  }
}

function checkMatch() {
  const [cardA, cardB] = flipped;
  const isMatch = cardA.dataset.pairId === cardB.dataset.pairId;

  if (isMatch) {
    cardA.classList.add('matched');
    cardB.classList.add('matched');
    cardA.setAttribute('aria-label', 'Matched card');
    cardB.setAttribute('aria-label', 'Matched card');
    cardA.setAttribute('tabindex', '-1');
    cardB.setAttribute('tabindex', '-1');
    matchedPairs++;
    flipped = [];
    if (matchedPairs === COLORS.length) {
      winMessage.hidden = false;
    }
  } else {
    lockBoard = true;
    setTimeout(() => {
      cardA.classList.remove('flipped');
      cardB.classList.remove('flipped');
      cardA.setAttribute('aria-label', 'Hidden card');
      cardB.setAttribute('aria-label', 'Hidden card');
      flipped = [];
      lockBoard = false;
    }, 800);
  }
}

function resetGame() {
  deck = createDeck();
  flipped = [];
  matchedPairs = 0;
  moves = 0;
  lockBoard = false;
  moveCounter.textContent = '0';
  winMessage.hidden = true;
  renderBoard();
}

newGameBtn.addEventListener('click', resetGame);

resetGame();
